INSERT INTO products (product_id, sku, product_name, brand, category, subcategory, description, attributes, price, is_b2b_only, created_at, updated_at) VALUES
  (1, 'FRZ-CAKE-001', 'Classic Vanilla Ice Cream Cake (8")', 'Atelier Patisserie', 'Frozen Desserts', 'Ice Cream Cakes', 'An 8-inch vanilla ice cream cake layered with chocolate fudge ribbon and finished with hand-piped buttercream rosettes. Made with real cream and Madagascar vanilla beans, frozen for 30+ day shelf life. Serves 8-12. Ships in dry-ice-cooled insulated packaging.', '{"size": "8 inch", "serves": 10, "allergens": ["dairy", "egg", "wheat"], "shelf_life_days": 30}', 34.99, FALSE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (2, 'FRZ-CAKE-002', 'Triple Chocolate Mousse Cake (6")', 'Atelier Patisserie', 'Frozen Desserts', 'Mousse Cakes', 'Decadent triple-layer mousse cake featuring dark chocolate ganache, milk chocolate mousse, and white chocolate cream over a chocolate sponge base. Sized for intimate gatherings; serves 6-8. Naturally gluten-free.', '{"size": "6 inch", "serves": 7, "allergens": ["dairy", "egg"], "gluten_free": true}', 28.99, FALSE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (3, 'FRZ-CAKE-003', 'Strawberry Shortcake Roll (Bulk Pack of 24)', 'Atelier Patisserie', 'Frozen Desserts', 'Cake Rolls', 'Foodservice bulk pack of individually-wrapped strawberry shortcake rolls. Vanilla sponge filled with real strawberry compote and Chantilly cream. Thaw-and-serve format with 5-minute prep time. Designed for restaurants, hotels, and corporate catering.', '{"pack_size": 24, "unit_weight_oz": 4, "allergens": ["dairy", "egg", "wheat"]}', 89.99, TRUE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (4, 'FRZ-CHE-001', 'New York Style Cheesecake (10")', 'Atelier Patisserie', 'Frozen Desserts', 'Cheesecakes', 'Classic dense New York-style cheesecake on a graham cracker crust. Made with Philadelphia cream cheese, sour cream, and farm-fresh eggs. Pre-sliced into 14 portions for foodservice convenience. Thaw 4-6 hours before serving.', '{"size": "10 inch", "slices": 14, "allergens": ["dairy", "egg", "wheat"]}', 42.99, FALSE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (5, 'FRZ-PIE-001', 'Apple Crumb Pie (9")', 'Heritage Bakehouse', 'Frozen Desserts', 'Pies', '9-inch double-layer apple pie with Granny Smith and Honeycrisp apples, cinnamon-brown sugar streusel, and an all-butter flaky crust. Frozen unbaked; bake from frozen in 60 minutes for that fresh-from-the-oven aroma.', '{"size": "9 inch", "serves": 8, "bake_from_frozen": true, "allergens": ["dairy", "wheat"]}', 18.99, FALSE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (6, 'BAK-DON-001', 'Glazed Yeast Donuts (Frozen Dough, Pack of 60)', 'Atelier Patisserie', 'Bakery', 'Donuts', 'Foodservice-grade frozen yeast donut dough rings ready for proof, fry, and glaze. Yields consistent texture and flavor at scale. Restaurant operators report 8-minute proof-to-plate time on standard equipment. Pack contains 60 unbaked rings.', '{"pack_size": 60, "preparation": "proof_fry_glaze", "allergens": ["wheat", "soy"]}', 64.99, TRUE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (7, 'BAK-CRO-001', 'Butter Croissants (Frozen, Pack of 48)', 'Heritage Bakehouse', 'Bakery', 'Pastries', 'All-butter laminated croissants in convenient frozen ready-to-bake format. 27 layers of butter folded into French-style dough. Bake from frozen in 18 minutes at 375°F. Ideal for hotel breakfast bars, cafés, and catering operations.', '{"pack_size": 48, "bake_time_min": 18, "allergens": ["dairy", "wheat", "egg"]}', 52.99, TRUE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (8, 'BAK-MUF-001', 'Blueberry Muffin Batter (4 lb tub)', 'Atelier Patisserie', 'Bakery', 'Muffins', 'Ready-to-portion blueberry muffin batter with real wild blueberries (15% by weight). One 4-pound tub yields 24 standard muffins. Stable at refrigerated temperatures for 21 days. Includes streusel topping pack.', '{"yield_units": 24, "weight_lb": 4, "refrigerated_shelf_days": 21}', 28.99, TRUE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (9, 'BAK-BRE-001', 'Artisan Sourdough Loaves (Pre-Baked, Pack of 12)', 'Heritage Bakehouse', 'Bakery', 'Bread', 'Wood-fired sourdough loaves with a 24-hour cold fermentation for that signature tang. Crackly crust, open crumb. Vacuum-sealed and frozen for retail or foodservice. Reheat 8 minutes for that just-baked experience.', '{"pack_size": 12, "unit_weight_oz": 18, "allergens": ["wheat"]}', 47.99, FALSE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (10, 'BAK-COO-001', 'Chocolate Chunk Cookie Dough Pucks (Pack of 200)', 'Atelier Patisserie', 'Bakery', 'Cookies', 'Pre-portioned 1.5 oz chocolate chunk cookie dough pucks. Real butter, semi-sweet chocolate chunks, and brown sugar. Bake from frozen in 13 minutes. Foodservice standard for hotels, cafeterias, and quick-service restaurants.', '{"pack_size": 200, "unit_weight_oz": 1.5, "allergens": ["dairy", "wheat", "egg"]}', 78.99, TRUE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (11, 'TOP-WHP-001', 'Whipped Topping (32 oz Tub)', 'Atelier Patisserie', 'Toppings', 'Whipped Topping', 'Original whipped topping in a 32-ounce tub. Stable at room temperature for 12 hours after thawing. Ideal for piping cake decorations, parfait layering, and dessert garnishing. Non-dairy formulation suitable for kosher applications.', '{"size_oz": 32, "non_dairy": true, "kosher": true}', 8.99, FALSE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (12, 'TOP-WHP-002', 'Whipped Topping (1-Gallon Pail)', 'Atelier Patisserie', 'Toppings', 'Whipped Topping', 'Foodservice gallon pail of whipped topping for bakeries, cafeterias, and high-volume operations. Same formulation as retail tub but in restaurant-friendly bulk packaging. Maintains structure for piped applications under varied temperatures.', '{"size_gal": 1, "non_dairy": true, "kosher": true}', 22.99, TRUE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (13, 'TOP-ICI-001', 'Vanilla Buttercream Icing (5 lb Pail)', 'Atelier Patisserie', 'Toppings', 'Icing', '5-pound pail of ready-to-use vanilla buttercream icing. Whip-stable, holds piping detail for 24 hours at room temperature. Pure vanilla extract. Use for cake assembly, cupcake topping, and decorative writing.', '{"weight_lb": 5, "allergens": ["dairy"]}', 36.99, TRUE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (14, 'TOP-ICI-002', 'Chocolate Fudge Icing (5 lb Pail)', 'Atelier Patisserie', 'Toppings', 'Icing', 'Decadent chocolate fudge icing made with Dutch-process cocoa and pure vanilla. 5-pound foodservice pail. Smooth, glossy finish ideal for layer cakes, sheet cakes, and brownies. No artificial colors.', '{"weight_lb": 5, "allergens": ["dairy"]}', 38.99, TRUE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (15, 'TOP-GLZ-001', 'Donut Glaze Concentrate (1 Gallon)', 'Atelier Patisserie', 'Toppings', 'Glaze', 'Concentrated donut glaze ready to dilute and apply. One gallon glazes approximately 1,200 standard yeast donuts. Sets to a clear satin finish with quick dry-time for bagging operations.', '{"size_gal": 1, "yield_units": 1200}', 24.99, TRUE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (16, 'PIZ-PIZ-001', 'Pepperoni Pizza Bites (Frozen, Pack of 120)', 'Roma Foods', 'Appetizers', 'Pizza Bites', 'Bite-sized pepperoni pizza appetizers. Sausage-stuffed dough filled with mozzarella and tomato sauce. Bake from frozen in 14 minutes at 400°F. Perfect for sports bars, concession stands, and party platters.', '{"pack_size": 120, "unit_weight_oz": 0.5, "allergens": ["dairy", "wheat", "pork"]}', 38.99, TRUE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (17, 'PIZ-PIZ-002', 'Cheese Pizza Crusts (12-inch, Pack of 20)', 'Roma Foods', 'Appetizers', 'Pizza Crusts', 'Par-baked 12-inch cheese pizza crusts. Topped with shredded mozzarella, no sauce — chefs add their own. Bake from frozen in 6-8 minutes. Stocked by independent pizzerias for emergency demand spikes.', '{"pack_size": 20, "diameter_inch": 12, "allergens": ["dairy", "wheat"]}', 67.99, TRUE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (18, 'PIZ-BRD-001', 'Garlic Knots (Pre-Proofed, Pack of 150)', 'Roma Foods', 'Appetizers', 'Bread Knots', 'Garlic-butter brushed pre-proofed dough knots. Bake from frozen in 11 minutes; brush with garlic-parsley butter after baking. Pizzeria standard side-item that pairs with all pasta and pizza menus.', '{"pack_size": 150, "allergens": ["dairy", "wheat"]}', 42.99, TRUE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (19, 'PIZ-MOZ-001', 'Mozzarella Sticks (Frozen, Pack of 200)', 'Roma Foods', 'Appetizers', 'Cheese Sticks', 'Breaded mozzarella cheese sticks, fully cooked and flash-frozen. Reheat in fryer (3 min, 350°F) or convection oven (8 min, 400°F). Whole-milk mozzarella. Foodservice case of 200 sticks.', '{"pack_size": 200, "allergens": ["dairy", "wheat", "egg"]}', 88.99, TRUE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (20, 'CST-CAK-001', 'Decorating Gel (Black, 8 oz Tube)', 'Atelier Patisserie', 'Decorating', 'Gel', 'Black writing gel in 8-ounce squeeze tube for cake decoration, signage, and detail work. Holds line definition without bleeding. Kosher-certified. Use for celebration cake messages and design accents.', '{"size_oz": 8, "color": "black", "kosher": true}', 4.99, FALSE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (21, 'CST-CAK-002', 'Decorating Gel (Red, 8 oz Tube)', 'Atelier Patisserie', 'Decorating', 'Gel', 'Red writing gel in 8-ounce squeeze tube. Vibrant true red without artificial dyes. Ideal for valentines, sports themes, and birthday cake decoration.', '{"size_oz": 8, "color": "red", "kosher": true}', 4.99, FALSE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (22, 'CST-SPR-001', 'Rainbow Sprinkles (5 lb Bulk)', 'Confection House', 'Decorating', 'Sprinkles', 'Classic rainbow jimmies sprinkles. 5-pound bulk bag for high-volume decorating operations. Stable color, no bleeding when applied to wet icing. Vegan and nut-free.', '{"weight_lb": 5, "vegan": true, "nut_free": true}', 22.99, TRUE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (23, 'CST-FON-001', 'White Rolled Fondant (5 lb Block)', 'Confection House', 'Decorating', 'Fondant', 'Pliable white rolled fondant for cake covering and decorative figures. 5-pound block. Pure vanilla flavoring, smooth texture, takes color cleanly. Used by professional decorators and serious home bakers.', '{"weight_lb": 5, "color": "white"}', 28.99, FALSE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (24, 'PLB-CAK-001', 'Vegan Chocolate Cake (8")', 'Heritage Bakehouse', 'Plant-Based', 'Vegan Cakes', 'Decadent vegan chocolate layer cake with dairy-free chocolate ganache. Made with oat milk and coconut cream. Naturally egg-free. 8-inch round serves 8-10. Tested to satisfy non-vegan palates.', '{"size": "8 inch", "serves": 9, "vegan": true, "allergens": ["wheat", "coconut"]}', 38.99, FALSE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (25, 'PLB-COO-001', 'Gluten-Free Chocolate Chip Cookies (Pack of 96)', 'Heritage Bakehouse', 'Plant-Based', 'GF Cookies', 'Gluten-free chocolate chip cookies that don''t taste gluten-free. Almond flour base, semi-sweet dark chocolate chunks. Pre-portioned 1 oz dough pucks, bake-from-frozen in 12 minutes. Restaurants pair with GF dessert menus.', '{"pack_size": 96, "gluten_free": true, "allergens": ["dairy", "egg", "tree_nut"]}', 89.99, TRUE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (26, 'PLB-MUF-001', 'Vegan Banana Walnut Muffin Batter (4 lb Tub)', 'Heritage Bakehouse', 'Plant-Based', 'Vegan Muffins', 'Plant-based banana-walnut muffin batter. Made with flax egg and oat milk. 4-pound tub yields 24 muffins. Wheat-flour based (not gluten-free). Refrigerated shelf life 21 days.', '{"yield_units": 24, "vegan": true, "allergens": ["wheat", "tree_nut"]}', 26.99, TRUE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (27, 'PLB-FRO-001', 'Sugar-Free Vanilla Frozen Dessert (1 Gallon)', 'Heritage Bakehouse', 'Plant-Based', 'Better-for-You', 'Sugar-free vanilla frozen dessert sweetened with monk fruit and stevia. 1-gallon tub for foodservice scoop applications. 50% fewer calories than traditional ice cream. Suitable for diabetic-friendly dessert menus.', '{"size_gal": 1, "sugar_free": true, "allergens": ["dairy"]}', 24.99, TRUE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (28, 'CTR-PLT-001', 'Mini Dessert Sampler Platter (60 Pieces)', 'Atelier Patisserie', 'Catering', 'Sampler Platters', 'Pre-arranged frozen mini-dessert sampler with 60 bite-sized pieces across 6 varieties: cheesecake bites, brownie squares, fruit tartlets, lemon bars, chocolate truffles, and éclairs. Thaw 2 hours, serve on platter. Catering and corporate event staple.', '{"pieces": 60, "varieties": 6, "allergens": ["dairy", "egg", "wheat"]}', 78.99, TRUE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (29, 'CTR-TRA-001', 'Custom Logo Cake Service', 'Atelier Patisserie', 'Catering', 'Custom Cakes', 'Custom corporate logo cake service. Submit logo artwork; we produce edible-image cake in your specified size (quarter sheet, half sheet, or full sheet). Lead time 5-7 business days. Minimum order 12 cakes for corporate accounts.', '{"min_order": 12, "lead_time_days": 6, "sizes": ["quarter_sheet", "half_sheet", "full_sheet"]}', 145.0, TRUE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (30, 'CTR-COF-001', 'Coffee-Service Pastry Assortment (Pack of 80)', 'Heritage Bakehouse', 'Catering', 'Assortments', 'Hotel and conference coffee-break pastry assortment. 80 pieces: croissants, mini-danish, scones, and breakfast cookies. Thaw overnight, plate and serve. Standard for business meetings and continental breakfast spreads.', '{"pack_size": 80, "varieties": 4, "allergens": ["dairy", "egg", "wheat"]}', 96.99, TRUE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (31, 'SEA-PUM-001', 'Pumpkin Spice Cheesecake (Seasonal, 10")', 'Atelier Patisserie', 'Seasonal', 'Specialty', 'Limited-edition pumpkin spice cheesecake on gingersnap crust. Real pumpkin puree, cinnamon, nutmeg, and clove. 10-inch round, 14 pre-cut slices. Available September through December. Popular thanksgiving menu item.', '{"size": "10 inch", "slices": 14, "seasonal": "fall", "allergens": ["dairy", "egg", "wheat"]}', 48.99, FALSE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (32, 'SEA-VAL-001', 'Heart-Shaped Red Velvet Cakes (Seasonal, Pack of 24)', 'Atelier Patisserie', 'Seasonal', 'Specialty', 'Heart-shaped individual red velvet cakes with cream cheese frosting. Pack of 24 single-serve portions. Available January through Valentine''s Day. Restaurant and gift-shop dessert staple for the holiday.', '{"pack_size": 24, "seasonal": "winter", "allergens": ["dairy", "egg", "wheat"]}', 64.99, TRUE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (33, 'SEA-HAL-001', 'Halloween Pumpkin Donuts (Seasonal, Pack of 60)', 'Atelier Patisserie', 'Seasonal', 'Specialty', 'Frosted pumpkin-shaped cake donuts with orange glaze and chocolate stem accent. Available September-October. Pack of 60 individually-decorated units. Popular with cafés, donut shops, and event caterers.', '{"pack_size": 60, "seasonal": "fall", "allergens": ["dairy", "egg", "wheat"]}', 54.99, TRUE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (34, 'BEV-SYR-001', 'Vanilla Bean Coffee Syrup (1 L Bottle)', 'Heritage Bakehouse', 'Beverages', 'Syrups', 'Premium vanilla bean coffee syrup with real Madagascar vanilla. 1-liter bottle dispenses approximately 33 drinks. Café and restaurant standard. Sugar-free version also available (PLB-SYR-001).', '{"size_ml": 1000, "yield_drinks": 33}', 14.99, FALSE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (35, 'BEV-FRP-001', 'Frappe Powder Base (5 lb Bag)', 'Heritage Bakehouse', 'Beverages', 'Frappe Mix', 'Frappe powder base for blended iced coffee and chocolate drinks. 5-pound bag yields ~120 16oz drinks. Just add ice, milk (or oat milk), and flavored syrup. Cafés use as the foundation for menu customization.', '{"weight_lb": 5, "yield_drinks": 120}', 38.99, TRUE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (36, 'RTL-BRO-001', 'Fudge Brownies (Boxed, Pack of 12)', 'Atelier Patisserie', 'Retail', 'Brownies', 'Individually-wrapped fudge brownies in a retail-ready 12-pack box. Decadent chocolate fudge texture, generous size. Shelf-stable 14 days. Common gas station, convenience store, and vending machine product.', '{"pack_size": 12, "shelf_stable_days": 14, "allergens": ["dairy", "egg", "wheat"]}', 12.99, FALSE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (37, 'RTL-CHE-001', 'Cheesecake Slices (Frozen, Pack of 14)', 'Atelier Patisserie', 'Retail', 'Single Servings', 'Pre-cut individual cheesecake slices in retail clamshell packaging. Pack of 14 single servings. New York style on graham cracker crust. Designed for grab-and-go retail and home freezer storage.', '{"pack_size": 14, "allergens": ["dairy", "egg", "wheat"]}', 28.99, FALSE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (38, 'RTL-COO-001', 'Soft-Baked Chocolate Chip Cookies (Pack of 16)', 'Atelier Patisserie', 'Retail', 'Cookies', 'Soft-baked chocolate chip cookies in resealable retail bag. Pack of 16 cookies. Stays soft for 21 days at room temperature. Real butter and semi-sweet chocolate chips. Popular pantry item.', '{"pack_size": 16, "shelf_days": 21, "allergens": ["dairy", "egg", "wheat"]}', 7.99, FALSE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (39, 'B2B-BUL-001', 'Bulk Cake Flour Blend (50 lb Bag)', 'Atelier Patisserie', 'B2B Bulk', 'Ingredients', 'Pre-blended cake flour with chemical leaveners optimized for tender crumb. 50-pound foodservice bag. Designed for bakery operations producing high volumes of layer cakes, sheet cakes, and cupcakes. Restaurant and commissary customers only.', '{"weight_lb": 50, "b2b_only": true, "allergens": ["wheat"]}', 78.99, TRUE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP()),
  (40, 'B2B-CON-001', 'Concentrated Cream Cheese (10 lb Block)', 'Atelier Patisserie', 'B2B Bulk', 'Ingredients', '10-pound block of high-fat cream cheese for cheesecake production and pastry filling applications. Commercial bakeries and foodservice operations only. Refrigerated 90-day shelf life.', '{"weight_lb": 10, "b2b_only": true, "allergens": ["dairy"]}', 64.99, TRUE, CURRENT_TIMESTAMP(), CURRENT_TIMESTAMP());
